1	export type Item = {
2	  type: string;
3	  cursed?: boolean;
4	  enchantment?: number;
5	};
6	
7	export type Customer = {
8	  yearsWithMHPCO: number;
9	};
10	
11	export type Damage = {
12	  itemType: string;
13	  amount: number;
14	};
15	
16	export type Incident = {
17	  cause: string;
18	  damages: readonly Damage[];
19	};
20	
21	export type QuoteStep = {
22	  op: "quote";
23	  items: readonly Item[];
24	};
25	
26	export type ClaimStep = {
27	  op: "claim";
28	  // Zero-based index of the quote step that created the policy.
29	  policy: number;
30	  incident: Incident;
31	};
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export type Scenario = {
36	  customer: Customer;
37	  steps: readonly Step[];
38	};
39	
40	export type QuoteResult = { premium: number };
41	export type ClaimResult = { payout: number; remainingCap: number };
42	
43	// One entry per scenario step, in order. Each step's `op` selects the shape.
44	export type StepResult = QuoteResult | ClaimResult;
45	
46	export type ScenarioResult = {
47	  results: StepResult[];
48	};
49	
50	const PROCESSING_FEE = 5;
51	
52	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
53	
54	const BASE_PREMIUMS: Record<string, number> = {
55	  sword: 100,
56	  amulet: 60,
57	  staff: 80,
58	  potion: 40,
59	  rune: 25,
60	  moonstone: 25,
61	};
62	
63	// Every percentage modifier is a delta computed against an *unmodified* base
64	// and summed with the others — modifiers never compound. Policy-wide ones use
65	// the policy base, item-specific ones the affected item's own base premium.
66	//
67	// Percentages stay in integer percent points: multiply first, divide by 100
68	// last. A float multiplier such as `base * 1.1` yields 110.00000000000001 for
69	// a sword and breaks the ceil. `(base * 10) / 100` gives exactly 10.
70	const percentOf = (amount: number, percent: number): number =>
71	  (amount * percent) / 100;
72	
73	// The MHPCO insures only the items on its price list. Anything else is a
74	// rejected policy, not a zero-priced one.
75	const lookUpByType = (table: Record<string, number>, type: string): number => {
76	  const value = table[type];
77	
78	  if (value === undefined) {
79	    throw new Error(`unknown item type: ${type}`);
80	  }
81	
82	  return value;
83	};
84	
85	// Rejecting uninsurable items is a rule of its own, so it is stated once and
86	// up front rather than left to fall out of whichever pricing step happens to
87	// look a type up first. Without this, a block of three unknown items would
88	// price through `baseOfGroup` untouched and only fail later, by luck, in the
89	// per-item surcharge pass.
90	const rejectUninsurableItems = (items: readonly Item[]): void => {
91	  for (const item of items) {
92	    lookUpByType(BASE_PREMIUMS, item.type);
93	  }
94	};
95	
96	const BLOCK_SIZE = 3;
97	const BLOCK_BASE_PREMIUM = 60;
98	
99	// How many of each key a collection holds. Items and damages both need this,
100	// over different fields — `keyOf` is the only thing that differs, so it is the
101	// only thing the caller supplies.
102	const tally = <Element>(
103	  elements: readonly Element[],
104	  keyOf: (element: Element) => string,
105	): Map<string, number> => {
106	  const counts = new Map<string, number>();
107	
108	  for (const element of elements) {
109	    const key = keyOf(element);
110	    counts.set(key, (counts.get(key) ?? 0) + 1);
111	  }
112	
113	  return counts;
114	};
115	
116	const countByType = (items: readonly Item[]): Map<string, number> =>
117	  tally(items, (item) => item.type);
118	
119	// Prices one type-group. A block of exactly three costs a flat rate instead of
120	// three individual premiums — deliberately including main items, not just the
121	// small components. Callers have already rejected uninsurable types, so the
122	// flat-rate branch skipping the price list is safe rather than a hole.
123	const basePremiumOfTypeGroup = (type: string, count: number): number =>
124	  count === BLOCK_SIZE
125	    ? BLOCK_BASE_PREMIUM
126	    : count * lookUpByType(BASE_PREMIUMS, type);
127	
128	const policyBaseOf = (items: readonly Item[]): number =>
129	  [...countByType(items)].reduce(
130	    (total, [type, count]) => total + basePremiumOfTypeGroup(type, count),
131	    0,
132	  );
133	
134	// A modifier rule: when `applies` holds for the subject, `percent` percent of
135	// the relevant base premium is added. A negative percent is a discount. Every
136	// rule whose predicate holds contributes; the deltas are summed, never
137	// compounded.
138	type ModifierRule<Subject> = {
139	  applies: (subject: Subject) => boolean;
140	  percent: number;
141	};
142	
143	const sumApplicablePercents = <Subject>(
144	  rules: ModifierRule<Subject>[],
145	  subject: Subject,
146	): number =>
147	  rules.reduce(
148	    (total, rule) => (rule.applies(subject) ? total + rule.percent : total),
149	    0,
150	  );
151	
152	// Policy-wide modifiers: each is a percentage of the policy base premium.
153	//
154	// Their subject is the circumstances under which the quote is issued — not the
155	// customer alone, and not the issued policy either (that is `IssuedPolicy`,
156	// which a claim reads). Today those circumstances are just who is asking and
157	// how many quotes they have had; rules that depend on more read the field they
158	// need off the same subject.
159	type QuoteCircumstances = {
160	  customer: Customer;
161	  // Zero-based ordinal among the customer's quotes in this scenario.
162	  quoteOrdinal: number;
163	};
164	
165	const LOYALTY_YEARS_THRESHOLD = 2;
166	const LOYALTY_DISCOUNT_PERCENT = -20;
167	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = -15;
168	
169	const POLICY_MODIFIER_RULES: ModifierRule<QuoteCircumstances>[] = [
170	  { applies: () => true, percent: FIRST_INSURANCE_SURCHARGE_PERCENT },
171	  {
172	    applies: ({ customer }) =>
173	      customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
174	    percent: LOYALTY_DISCOUNT_PERCENT,
175	  },
176	  {
177	    applies: ({ quoteOrdinal }) => quoteOrdinal > 0,
178	    percent: FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT,
179	  },
180	];
181	
182	const policyModifierDelta = (
183	  policyBase: number,
184	  circumstances: QuoteCircumstances,
185	): number =>
186	  percentOf(
187	    policyBase,
188	    sumApplicablePercents(POLICY_MODIFIER_RULES, circumstances),
189	  );
190	
191	// Item-specific modifiers: each is a percentage of the affected item's own
192	// base premium.
193	const CURSE_SURCHARGE_PERCENT = 50;
194	const HIGH_ENCHANTMENT_THRESHOLD = 5;
195	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
196	
197	const ITEM_MODIFIER_RULES: ModifierRule<Item>[] = [
198	  { applies: (item) => item.cursed === true, percent: CURSE_SURCHARGE_PERCENT },
199	  {
200	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
201	    percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
202	  },
203	];
204	
205	const itemModifierDelta = (item: Item): number =>
206	  percentOf(
207	    lookUpByType(BASE_PREMIUMS, item.type),
208	    sumApplicablePercents(ITEM_MODIFIER_RULES, item),
209	  );
210	
211	const quote = (
212	  items: readonly Item[],
213	  circumstances: QuoteCircumstances,
214	): number => {
215	  rejectUninsurableItems(items);
216	
217	  const policyBase = policyBaseOf(items);
218	  const modifiers =
219	    policyModifierDelta(policyBase, circumstances) +
220	    items.reduce((total, item) => total + itemModifierDelta(item), 0);
221	
222	  // Rounding is in the MHPCO's favour: premiums round up.
223	  return Math.ceil(policyBase + modifiers) + PROCESSING_FEE;
224	};
225	
226	// Insurance values are what an item is insured FOR, distinct from the base
227	// premium charged to insure it.
228	const INSURANCE_VALUES: Record<string, number> = {
229	  sword: 1000,
230	  amulet: 600,
231	  staff: 800,
232	  potion: 400,
233	  rune: 250,
234	  moonstone: 250,
235	};
236	
237	const DEDUCTIBLE_PER_DAMAGE = 100;
238	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
239	
240	const insuranceSumOf = (items: readonly Item[]): number =>
241	  items.reduce(
242	    (sum, item) => sum + lookUpByType(INSURANCE_VALUES, item.type),
243	    0,
244	  );
245	
246	// A policy as a claim sees it: the items it covers, and how much of its cap
247	// is still available. Successive claims against the same policy draw the cap
248	// down, so `remainingCap` is state that outlives the claim step that reads it.
249	type IssuedPolicy = {
250	  items: readonly Item[];
251	  remainingCap: number;
252	};
253	
254	const issuePolicy = (items: readonly Item[]): IssuedPolicy => ({
255	  items,
256	  remainingCap: CAP_MULTIPLE_OF_INSURANCE_SUM * insuranceSumOf(items),
257	});
258	
259	// A reimbursement clause: when `applies` holds for the damaged item, the
260	// damage is reimbursed at `percent` of its amount.
261	//
262	// Unlike the premium modifiers above, clauses do NOT sum. When several apply
263	// the most restrictive one wins — the lowest percentage. So a clause table
264	// needs no ordering to be correct, and adding a clause can only ever lower a
265	// payout, never raise it.
266	type ReimbursementClause = {
267	  applies: (item: Item) => boolean;
268	  percent: number;
269	};
270	
271	const FULL_REIMBURSEMENT_PERCENT = 100;
272	const HALVED_REIMBURSEMENT_ENCHANTMENT = 8;
273	const HALVED_REIMBURSEMENT_PERCENT = 50;
274	
275	const REIMBURSEMENT_CLAUSES: ReimbursementClause[] = [
276	  {
277	    applies: (item) =>
278	      (item.enchantment ?? 0) >= HALVED_REIMBURSEMENT_ENCHANTMENT,
279	    percent: HALVED_REIMBURSEMENT_PERCENT,
280	  },
281	];
282	
283	// Full reimbursement is the default: with no clause applying, the damage is
284	// covered in full.
285	const reimbursementPercentFor = (item: Item): number =>
286	  REIMBURSEMENT_CLAUSES.reduce(
287	    (percent, clause) =>
288	      clause.applies(item) ? Math.min(percent, clause.percent) : percent,
289	    FULL_REIMBURSEMENT_PERCENT,
290	  );
291	
292	// The damaged item a damage entry refers to, or undefined if the policy does
293	// not cover that type. Matched by type alone, so with two swords insured both
294	// sword damages resolve to the first. That is harmless while every item of a
295	// type is interchangeable for reimbursement purposes; the case that forces a
296	// positional match is rejecting more damage entries of a type than the policy
297	// covers, which needs a count rather than a lookup.
298	const insuredItemFor = (
299	  policy: IssuedPolicy,
300	  damage: Damage,
301	): Item | undefined =>
302	  policy.items.find((item) => item.type === damage.itemType);
303	
304	// A damage entry that has passed validation, paired with the insured item it
305	// was resolved against. Producing this is what the validation pass is *for*:
306	// downstream code takes the item as given rather than re-looking it up and
307	// re-handling a "not covered" case that can no longer occur.
308	type AdmittedDamage = {
309	  damage: Damage;
310	  damagedItem: Item;
311	};
312	
313	const countDamagesByType = (damages: readonly Damage[]): Map<string, number> =>
314	  tally(damages, (damage) => damage.itemType);
315	
316	// Admits an incident's damages, or refuses the claim outright. Stated here,
317	// once and up front, for the same reason `rejectUninsurableItems` is: a
318	// rejection is a rule in its own right, not something that should fall out of
319	// whichever computation step happens to trip over it first.
320	//
321	// Running before any money is computed also keeps the settlement total — a
322	// function that can throw partway through an accumulation is doing control
323	// flow through the accumulator.
324	//
325	// This is the incident-level pass, so a rule that needs to see all the damages
326	// at once — counting entries per type against what the policy covers — has a
327	// home here, whereas it could never live inside a per-damage function.
328	const admitDamages = (
329	  policy: IssuedPolicy,
330	  incident: Incident,
331	): AdmittedDamage[] => {
332	  // A policy cannot lose more of a thing than it insures.
333	  const insuredCounts = countByType(policy.items);
334	
335	  for (const [itemType, damagedCount] of countDamagesByType(incident.damages)) {
336	    const insuredCount = insuredCounts.get(itemType) ?? 0;
337	
338	    if (damagedCount > insuredCount) {
339	      throw new Error(
340	        `more ${itemType} damages than the policy covers: ` +
341	          `${damagedCount} of ${insuredCount}`,
342	      );
343	    }
344	  }
345	
346	  return incident.damages.map((damage) => {
347	    // Damage is a loss, never a credit.
348	    if (damage.amount < 0) {
349	      throw new Error(`negative damage amount: ${damage.amount}`);
350	    }
351	
352	    const damagedItem = insuredItemFor(policy, damage);
353	
354	    // A policy only answers for what it covers.
355	    if (damagedItem === undefined) {
356	      throw new Error(`item not covered by the policy: ${damage.itemType}`);
357	    }
358	
359	    return { damage, damagedItem };
360	  });
361	};
362	
363	// What a single admitted damage is reimbursable for: the reimbursement its
364	// clauses allow, less the deductible. The deductible is charged once per
365	// damaged item, not once per incident, so it belongs here rather than at the
366	// incident level. The policy's cap is NOT applied here — it limits the
367	// incident as a whole, so only `settleClaim` can apply it.
368	//
369	// The clauses grade the reimbursement by the *damaged item's* properties
370	// (enchantment, material), which is why the resolved item travels with the
371	// damage instead of the policy being passed in to look it up again.
372	const reimbursableForDamage = ({
373	  damage,
374	  damagedItem,
375	}: AdmittedDamage): number =>
376	  percentOf(damage.amount, reimbursementPercentFor(damagedItem)) -
377	  DEDUCTIBLE_PER_DAMAGE;
378	
379	// Settles one incident against a policy, returning the payout and the policy
380	// as it stands afterwards. The cap is drawn down here — that is what makes a
381	// second claim against the same policy see less headroom than the first.
382	const settleClaim = (
383	  policy: IssuedPolicy,
384	  incident: Incident,
385	): { payout: number; policy: IssuedPolicy } => {
386	  // Admit every damage before paying for any: a claim is refused as a whole,
387	  // so no part of it should be priced until all of it is known to be valid.
388	  const admitted = admitDamages(policy, incident);
389	
390	  const reimbursable = admitted.reduce(
391	    (total, admittedDamage) => total + reimbursableForDamage(admittedDamage),
392	    0,
393	  );
394	
395	  // Rounding is in the MHPCO's favour: payouts round down, mirroring the
396	  // premium's round up.
397	  // The policy pays at most what is left of its cap.
398	  const payout = Math.min(Math.floor(reimbursable), policy.remainingCap);
399	
400	  return {
401	    payout,
402	    policy: { ...policy, remainingCap: policy.remainingCap - payout },
403	  };
404	};
405	
406	// What the scenario has established by the time a step runs. Threaded through
407	// the steps in order: each step reads it, and hands the next step the progress
408	// its own execution made.
409	type ScenarioProgress = {
410	  // How many quotes the customer has already been given. Only quote steps
411	  // advance this, so an op that is not a quote leaves it untouched.
412	  quotesSoFar: number;
413	  // Policies created by earlier quote steps, keyed by their step index — the
414	  // handle a later claim step names in its `policy` field.
415	  policies: Map<number, IssuedPolicy>;
416	};
417	
418	// The policy a claim step names. A claim against an index no quote step
419	// created currently settles against an empty policy: no items, so every damage
420	// is uncovered, and a zero cap. That is a placeholder standing in for a rule
421	// nobody has written yet, not a decision — the honest behaviour is almost
422	// certainly to reject the claim outright, the way an unknown item type is
423	// rejected. Named here so the choice is visible at the point it is made, and
424	// so the test that pins it down has one place to change.
425	const policyClaimedAgainst = (
426	  policies: ReadonlyMap<number, IssuedPolicy>,
427	  policyIndex: number,
428	): IssuedPolicy => policies.get(policyIndex) ?? issuePolicy([]);
429	
430	// Runs one step against the progress so far, returning its result alongside
431	// the progress the *next* step inherits. Dispatch on `step.op` lives here:
432	// a new op is a new branch, and the loop below is unaffected.
433	const runStep = (
434	  step: Step,
435	  stepIndex: number,
436	  customer: Customer,
437	  progress: ScenarioProgress,
438	): { result: StepResult; progress: ScenarioProgress } => {
439	  if (step.op === "claim") {
440	    const settled = settleClaim(
441	      policyClaimedAgainst(progress.policies, step.policy),
442	      step.incident,
443	    );
444	
445	    return {
446	      result: {
447	        payout: settled.payout,
448	        remainingCap: settled.policy.remainingCap,
449	      },
450	      // The drawn-down policy replaces the one the claim was made against, so
451	      // the next claim against it starts from the reduced cap.
452	      progress: {
453	        ...progress,
454	        policies: new Map(progress.policies).set(step.policy, settled.policy),
455	      },
456	    };
457	  }
458	
459	  return {
460	    result: {
461	      premium: quote(step.items, {
462	        customer,
463	        quoteOrdinal: progress.quotesSoFar,
464	      }),
465	    },
466	    progress: {
467	      quotesSoFar: progress.quotesSoFar + 1,
468	      policies: new Map(progress.policies).set(
469	        stepIndex,
470	        issuePolicy(step.items),
471	      ),
472	    },
473	  };
474	};
475	
476	export const runScenario = (scenario: Scenario): ScenarioResult => {
477	  const results: StepResult[] = [];
478	  let progress: ScenarioProgress = { quotesSoFar: 0, policies: new Map() };
479	
480	  for (const [stepIndex, step] of scenario.steps.entries()) {
481	    const stepRun = runStep(step, stepIndex, scenario.customer, progress);
482	
483	    results.push(stepRun.result);
484	    progress = stepRun.progress;
485	  }
486	
487	  return { results };
488	};
