1	import { runScenario, type Scenario } from "./claim-office.js";
2	
3	const readStdin = async (): Promise<string> => {
4	  let input = "";
5	
6	  process.stdin.setEncoding("utf8");
7	
8	  for await (const chunk of process.stdin) {
9	    input += chunk;
10	  }
11	
12	  return input;
13	};
14	
15	// The CLI's contract on the happy path: a scenario in on stdin, its results
16	// out on stdout. Everything that can go wrong throws — reporting a failure is
17	// the caller's job, not this function's, so the success path reads straight
18	// through without being interleaved with error handling.
19	const runScenarioFromStdin = async (): Promise<void> => {
20	  const scenario = JSON.parse(await readStdin()) as Scenario;
21	
22	  process.stdout.write(JSON.stringify(runScenario(scenario)));
23	};
24	
25	try {
26	  await runScenarioFromStdin();
27	} catch (error) {
28	  // A rejected scenario is a described failure, not a crash. `exitCode` rather
29	  // than `exit(1)` so the pending stderr write flushes before the process ends.
30	  const description = error instanceof Error ? error.message : String(error);
31	
32	  process.stderr.write(`${description}\n`);
33	  process.exitCode = 1;
34	}
