1	import { describe, it, expect } from "vitest";
2	import { spawn } from "node:child_process";
3	import { runScenario } from "./claim-office.js";
4	
5	type CliRun = { stdout: string; stderr: string; exitCode: number };
6	
7	// Exercises the real stdin/stdout contract by running the CLI as a child
8	// process, rather than importing it.
9	const runCli = (input: string): Promise<CliRun> =>
10	  new Promise((resolve, reject) => {
11	    const child = spawn("npx", ["tsx", "src/cli.ts"], {
12	      stdio: ["pipe", "pipe", "pipe"],
13	    });
14	
15	    let stdout = "";
16	    let stderr = "";
17	
18	    child.stdout.on("data", (chunk: Buffer) => (stdout += chunk));
19	    child.stderr.on("data", (chunk: Buffer) => (stderr += chunk));
20	    child.on("error", reject);
21	    child.on("close", (exitCode) =>
22	      resolve({ stdout, stderr, exitCode: exitCode ?? 0 }),
23	    );
24	
25	    child.stdin.end(input);
26	  });
